let db=null,route='',config=null,characterWork=null,intakeBusy=false;const drafts=new Map(),connectionState=new Map();
const clone=x=>JSON.parse(JSON.stringify(x));
async function request(path,body){const r=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await r.json();if(!r.ok){const error=Error([value.error,...(value.details||[])].filter(Boolean).join('\n'));error.status=r.status;throw error;}return value}
