async function rebaseForm(n){await refresh();const latest=storedRecord(n._identity);if(n._identity?.[1]&&!latest)throw Error('この対象は削除されています。下書きは保持しています。新しい登録先へ内容を移してください。');const apply=()=>{n.dataset.revision=db.revision;n._baseline=latest?clone(latest):null;mark(n);feedback(n.querySelector('[data-form-status]'),'最新の保存状態を取得しました。下書きは維持しています。内容を確認して保存してください。');const b=n.querySelector('[data-rebase]');if(b)b.hidden=true};if(JSON.stringify(n._baseline)!==JSON.stringify(latest??null)){const body=E('div');body.append(E('p','別の操作で保存済みの内容が変わっています。次の最新内容を確認してください。下書きの入力欄は変更しません。'));const pre=E('pre',JSON.stringify(latest,null,2));pre.style.whiteSpace='pre-wrap';pre.style.maxHeight='40vh';pre.style.overflow='auto';body.append(pre);confirmDialog('保存内容と下書きを確認',body,apply,{labelText:'最新を確認して下書きを維持する'})}else apply()}
function currentRevision(form){return Number(form.dataset.revision)}
function draftLocations(){return [...drafts].map(([key,d])=>{let x;try{x=JSON.parse(key)}catch{}const kind=x?.[0],id=x?.[1],where=x?.[2],names={works:'作品設定',actors:'アクター設定',voices:'ボイス設定',character:'配役設定',track:'Track設定',unit:'ユニット',block:'Block設定',levels:'レベル対応表',cg:'CG設定',cgsettings:'CG生成設定',reading:'読み指定','reading-new':'新しい読み指定'};let text=names[kind]||({config:'接続設定',extensions:'追加情報'}[key])||'編集欄';if(kind==='works')text+='：'+(work(id)?.title||'新しい作品');else if(kind==='actors')text+='：'+(actor(id)?.name||'新規');else if(kind==='voices')text+='：'+(voice(id)?.name||'新規');else if(id)text+='：'+id;if(Array.isArray(where)){const t=work(where[0])?.tracks?.find(t=>t.id===where[1]);if(t)text+=' ／ '+t.title}if(d.changed_fields?.length)text+='（'+d.changed_fields.join('、')+'）';if(d.error)text+=' ／ '+d.error;return {text,route:d.route}})}
function warnUnsaved(){if(drafts.size)report('自動保存待ち、または保存できていない入力があります。操作はそのまま続行できます。\n'+draftLocations().map(x=>x.text).join('\n'),true)}
function dirtyStatus(){const count=drafts.size;$('saveState').textContent=count?'未保存の編集 '+count+'件':'保存済み';$('importOpen').disabled=false;$('importOpen').title='';$('intakeRun').disabled=intakeBusy;const notice=$('unsavedNotice');if(!notice)return;notice.hidden=!count;notice.replaceChildren();if(count){notice.append(E('strong','未保存の編集 '+count+'件：操作はそのまま続行できます。'));const list=E('ul');for(const item of draftLocations()){const li=E('li');if(item.route)li.append(link(item.text,item.route));else li.textContent=item.text;list.append(li)}notice.append(list,E('small','画面移動後も下書きを保持します。保存できていない欄は、その欄に理由を表示します。'))}}
function capture(form){const values={};for(const n of form.elements){if(!n.name||n.type==='file'||n.dataset.structuredControl)continue;values[n.name]=n.type==='checkbox'?n.checked:n.value}return values}
