function renderSidebar(){const root=$('workLinks');root.replaceChildren();for(const w of db.works){const a=E('a',w.title);a.href='#work/'+encodeURIComponent(w.id);if(route==='work/'+w.id)a.setAttribute('aria-current','page');root.append(a);for(const t of w.tracks||[]){const item=link('#'+t.number+' '+t.title,trackRoute(w.id,t.id));item.className='track-link';if(trackContext()[1]===t.id)item.setAttribute('aria-current','page');root.append(item)}}for(const a of document.querySelectorAll('[data-nav]')){const name=a.dataset.nav;if(route.startsWith(name)||name==='works'&&route.startsWith('work/'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')}const crumbs=$('breadcrumb');crumbs.replaceChildren();const parts=routeParts();if(parts[0]==='actor'){crumbs.append(link('資産','actors'),E('span','›'),E('strong',actor(parts[1])?.name||'新しいアクター'))}else if(parts[0]==='work'){crumbs.append(link('作品一覧','works'),E('span','›'),E('strong',work(parts[1])?.title||'新しい作品'))}else if(['track','studio','cg','cgsettings','novel'].includes(parts[0])){const [wid,tid]=trackContext(),w=work(wid),t=w?.tracks?.find(t=>t.id===tid);crumbs.append(link('作品一覧','works'),E('span','›'),link(w?.title||'作品','work/'+encodeURIComponent(wid)),E('span','›'),E('strong',t?.title||'Track'))}else crumbs.append(E('strong',({actors:'資産 ／ アクター／モデル',voices:'資産 ／ ボイスライブラリ',works:'作品一覧'}[parts[0]]||'つむごえ')))}
