function render(){if(!db)return;try{route=decodeURIComponent(location.hash.slice(1)||'actors')}catch{route='actors'};$('main').replaceChildren();renderSidebar();const [page,id]=routeParts();if(page==='new-actor')actorEditor(null);else if(page==='new-work')workEditor(null);else if(page==='new-voice')voiceLibrary(null,true);else if(page==='actor')actorEditor(id);else if(page==='voices')voiceLibrary(id);else if(page==='novel')renderNovel(...trackContext());else if(page==='cg')renderCG(...trackContext());else if(page==='cgsettings')renderCGSettings(...trackContext());else if(page==='studio')renderStudio(...trackContext());else if(page==='track')trackEditor(...trackContext());else if(page==='work')workEditor(id);else if(page==='works')workList();else actorList();dirtyStatus()}
async function openConfig(){config=await request('config');const root=$('configContent');root.replaceChildren();const n=form('config',async n=>{const result={...config,port:Number(value(n,'port')),tts:{...config.tts,...Object.fromEntries(['project_dir','python','worker','checkpoint'].map(k=>[k,value(n,'tts_'+k)]))},comfyui:{...config.comfyui,endpoint:value(n,'comfyui_endpoint')},ffmpeg_path:value(n,'ffmpeg_path')};await request('config-save',{config:result});drafts.delete(n.dataset.key);dirtyStatus();feedback(n.querySelector('[data-form-status]'),'接続設定を保存しました。ポートの変更は次回起動時に反映します。');report('接続設定を保存しました。')});const engine=section(n,'IRODORI-TTS（ローカルワーカー）');for(const [key,title]of [['project_dir','IRODORI-TTSのフォルダ'],['python','IRODORI-TTSのPython'],['worker','接続ワーカー'],['checkpoint','モデルのチェックポイント']])field(engine,title,'tts_'+key,config.tts[key]);const other=section(n,'ComfyUI・アプリ');field(other,'ComfyUIの接続先','comfyui_endpoint',config.comfyui.endpoint);field(other,'ffmpegのパス（後の増分で使用）','ffmpeg_path',config.ffmpeg_path);field(other,'アプリのポート番号','port',config.port,'number');formActions(n,'接続設定を保存');root.append(n);restore(n,n.dataset.key);connectionTools(root);const ext=E('details');ext.append(E('summary','取り込んだ追加情報を編集'));const extbox=form('extensions',()=>{});field(extbox,'追加情報','extra',JSON.stringify(db.extensions,null,2),'json');formActions(extbox);restore(extbox,'extensions');ext.append(extbox);root.append(ext);if(!$('config').open)$('config').showModal()}
$('configOpen').onclick=()=>openConfig().catch(e=>report(e.message,true));

function openIntake(wid=workId(),mode='new',tid=null){warnUnsaved();const sel=$('intakeWork');sel.replaceChildren();for(const [id,name]of [['','作品を選択'],...db.works.map(w=>[w.id,w.title])]){const o=E('option',name);o.value=id;sel.append(o)}sel.value=wid||'';$('intakeMode').value=mode;updateIntakeTracks(tid);feedback($('intakeResult'),drafts.size?'保存待ちの箇所：'+draftLocations().map(x=>x.text).join('、')+'。取り込みは続行できます。':'');$('intake').showModal();$('intakeText').focus()}
function updateIntakeTracks(tid=null){const w=work($('intakeWork').value),sel=$('intakeTrack');sel.replaceChildren();for(const t of w?.tracks||[]){const o=E('option','#'+t.number+' '+t.title);o.value=t.id;sel.append(o)}if(tid)sel.value=tid;sel.disabled=$('intakeMode').value!=='update';$('intakeTarget').textContent='JSONの種別は自動判別します。Track追加では既存Trackを変更しません。更新はここで選んだTrackだけに適用します。種別キーがない情報は保持し、空配列の場合は消去前に確認します。'}
$('importOpen').onclick=()=>{const [wid,tid]=trackContext();openIntake(wid||workId(),'new',tid)};
$('intakeWork').onchange=()=>updateIntakeTracks();$('intakeMode').onchange=()=>updateIntakeTracks();
async function performIntake(body){const result=await request('import',body);if(result.confirmation_required){const d=result.delete_counts;confirmDialog('取り込みで消去される内容を確認', '単位 '+d.units+'件 ／ 台詞 '+d.lines+'件 ／ CG枠 '+d.cgs+'件\n音声ファイル '+d.audio_files+'件（関連解除 '+d.audio_links+'件）／ 画像ファイル '+d.image_files+'件\n'+(result.empty_keys.length?'空への同期：'+result.empty_keys.join('・')+'\n':'')+'この取り込み先だけに適用します。JSONに含まれない種別は保持します。',()=>performIntake({...body,confirmation:result.confirmation}),{checkbox:true,labelText:'確認した内容で取り込む'});return}await refresh();if(result.track_id)location.hash=trackRoute(result.work_id,result.track_id);render();const r=result.report;feedback($('intakeResult'),'取り込み完了：追加 '+r.added+'件 ／ 更新 '+r.updated+'件 ／ 削除 '+r.deleted+'件\n'+r.items.map(x=>x.kind+' '+x.id+'：'+x.operation).join('\n')+(r.retained_fields?.length?'\n追加情報として保持：'+r.retained_fields.join('、'):'')+(r.warnings.length?'\n取り込まなかった項目：\n'+r.warnings.join('\n'):''));report('取り込み完了：追加 '+r.added+'件 ／ 更新 '+r.updated+'件 ／ 削除 '+r.deleted+'件')}
$('intakeRun').onclick=async()=>{if(intakeBusy)return;warnUnsaved();const button=$('intakeRun');intakeBusy=true;button.disabled=true;try{await performIntake({text:$('intakeText').value,work_id:$('intakeWork').value||null,track_id:$('intakeTrack').value||null,track_mode:$('intakeMode').value,revision:db.revision})}catch(e){feedback($('intakeResult'),e.message,true)}finally{intakeBusy=false;dirtyStatus()}};
