function readingPreview(lines,w){const dict=new Map(w.readings.map(r=>[r.text,r.reading]));return lines.map(l=>l.replace(/\[([^\[\]]+)\]/g,(_,k)=>dict.get(k)||k))}
function highlightLines(parent,lines,w,tts=false){parent.replaceChildren();const dict=new Map(w.readings.map(r=>[r.text,r.reading]));for(const line of lines){const p=E('p',undefined,'script-line');let start=0;for(const m of line.matchAll(/\[([^\[\]]+)\]/g)){p.append(document.createTextNode(line.slice(start,m.index)));const mark=E('mark',tts?(dict.get(m[1])||m[1]):m[1]);mark.title=dict.get(m[1])?'読み：'+dict.get(m[1]):'読み未登録';if(!dict.get(m[1]))mark.className='missing-reading';p.append(mark);start=m.index+m[0].length}p.append(document.createTextNode(line.slice(start)));if(!line)p.append(E('span','〔間〕','muted'));parent.append(p)}}
