function renderLevels(parent,w,t){parent.append(E('h2','レベル対応表'),E('p','レベルごとにキャプションと参照ボイスを設定します。空の表から始められます。','muted'));const n=form(draftKey('levels',t.id,w.id),async n=>{await request('dialogue-levels',{work_id:w.id,track_id:t.id,levels:parseObject(value(n,'levels'),'レベル対応表'),revision:currentRevision(n)});drafts.delete(n.dataset.key);await refresh();render();report('レベル対応表を保存しました。影響する単位だけ「変更あり」になります。')});const hidden=E('textarea');hidden.name='levels';hidden.hidden=true;hidden.value=JSON.stringify(t.levels||{});n.append(hidden);const rows=E('div');n.append(rows);const add=E('input');add.setAttribute('aria-label','追加するレベル名');n.append(label('追加するレベル名',add),action('レベルを追加',()=>{const values=JSON.parse(hidden.value),key=add.value;if(!key)throw Error('レベル名を入力してください。');if(Object.hasOwn(values,key))throw Error('同じレベル名が既にあります。');hidden.value=JSON.stringify({...values,[key]:{caption:'',voice_id:null}});mark(n);draw()}));formActions(n,'レベル対応表を保存');parent.append(n);restore(n,n.dataset.key);function draw(){rows.replaceChildren();for(const [key,row]of Object.entries(JSON.parse(hidden.value))){const card=E('section');card.append(E('h3',key));const caption=field(card,'キャプション','caption_'+key,row.caption||'','textarea'),v=select(card,'参照ボイス','voice_'+key,[['','配役の既定を使う'],...db.voices.map(v=>[v.id,v.name])],row.voice_id);const change=()=>{const x=JSON.parse(hidden.value);x[key]={...x[key],caption:caption.value,voice_id:v.value||null};hidden.value=JSON.stringify(x);mark(n)};caption.oninput=change;v.onchange=change;card.append(action('このレベルを対応表から外す',()=>{const x=JSON.parse(hidden.value);delete x[key];hidden.value=JSON.stringify(x);mark(n);draw()}));rows.append(card)}}draw()}
